// Global/File Scope (Initialized)
int global_counter = 10;
// Allocated in .data section

// Global/File Scope (Uninitialized)
static int file_index;
// Allocated in .bss section (Zeroed by OS loader)

// Function Scope (Initialized)
void func() {
    static float pi = 3.14f;
    // Persists across calls (in .data)
}

// Function Scope (Uninitialized)
void another_func() {
    static int index;
    // Persists across calls (in .bss, initialized to 0)
}

// Static Class Member (Definition/Initialization)
class Config {
    static const int MAX_SIZE;
};
const int Config::MAX_SIZE = 100; // Allocated in .data
